from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}


def _policy_error(status: str, member: dict) -> str | None:
    """Return the per-status validation error message, else None."""
    if status == "lapsed":
        if ("expired_days" not in member
                or not isinstance(member["expired_days"], int)
                or member["expired_days"] < 0):
            return "bad expiry"
    elif status == "suspended":
        if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return "bad strikes"
        if member["strikes"] >= MAX_STRIKES:
            return "too many strikes"
    return None


def _surcharge_and_outcome(status: str, member: dict) -> tuple[int, str]:
    """Extra fee above the base tier, and the membership status to grant."""
    if status == "lapsed":
        if member["expired_days"] <= GRACE_DAYS:
            return LATE_FEE, "renewed"
        return REINSTATE_SURCHARGE, "reinstated"
    if status == "suspended":
        return TIER_FEES[member["tier"]] // 2, "reactivated"
    return 0, "renewed"


